it('passes an undefined rejection to onError as an Error cause (spec: specs/hal-engine-config-hooks/spec.md#9)', async () => {
  const provider: AIProvider = {
    // eslint-disable-next-line require-yield
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      throw undefined;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
  const session: ChatSession = {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content: 'hello', timestamp: '2026-01-01T00:00:00.000Z'}],
  };
  const observed: Error[] = [];
  const orchestrator = createChatOrchestrator(
    provider,
    new PromptBuilder({identity: 'You are a test assistant.'}),
    undefined,
    {hooks: {onError: async (_session, error) => void observed.push(error)}}
  );

  const outcome = await orchestrator.processMessage(session).then(
    () => ({rejected: false}),
    (reason: unknown) => ({rejected: true, reason})
  );

  expect({
    outcome,
    count: observed.length,
    isError: observed[0] instanceof Error,
    hasCause: observed[0] ? Object.hasOwn(observed[0], 'cause') : false,
    cause: observed[0]?.cause,
  }).toEqual({
    outcome: {rejected: true, reason: undefined},
    count: 1,
    isError: true,
    hasCause: true,
    cause: undefined,
  });
});

